const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon for northern Afghanistan (rough bounding box)
  const geometry = ee.Geometry.Polygon([
    [[60.5, 37.5], [60.5, 36.0], [72.0, 36.0], [72.0, 37.5]]
  ]);

  // Define baseline years (2000-2013) and target year (2018)
  const baselineYears = ee.List.sequence(2000, 2013);
  const targetYear = 2018;
  const months = [6, 7, 8]; // June, July, August

  // 2. Data Acquisition - MODIS NDVI (MOD13Q1)
  const modisCol = ee.ImageCollection('MODIS/006/MOD13Q1')
    .select(['NDVI', 'SummaryQA']);

  // Function to filter by year and months, and mask low quality pixels
  function filterAndMask(year) {
    const startDate = ee.Date.fromYMD(year, 6, 1);
    const endDate = ee.Date.fromYMD(year, 9, 1); // August 31 inclusive
    let col = modisCol
      .filterDate(startDate, endDate)
      .filter(ee.Filter.calendarRange(months[0], months[2], 'month'));
    // Mask out poor quality (SummaryQA = 2 or 3 for snow/ice and clouds)
    col = col.map(function(img) {
      const qa = img.select('SummaryQA');
      const mask = qa.lt(2); // Keep only Good (0) and Marginal (1)
      return img.select('NDVI').updateMask(mask).multiply(0.0001);
    });
    return col;
  }

  // 3. Process baseline years
  let baselineMeans = [];
  for (let i = 2000; i <= 2013; i++) {
    const col = filterAndMask(i);
    const count = col.size().getInfo();
    if (count === 0) {
      console.log(`Year ${i}: No images`);
      baselineMeans.push(null);
      continue;
    }
    // Compute mean NDVI for the year's JJA period
    const meanImg = col.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });
    const meanVal = stats.get('NDVI').getInfo();
    // Check for valid pixels
    const pixelCount = meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();
    if (pixelCount === 0) {
      console.log(`Year ${i}: No valid pixels after masking`);
      baselineMeans.push(null);
    } else {
      console.log(`Year ${i}: Images=${count}, Mean NDVI=${meanVal ? meanVal.toFixed(4) : 'null'}, Pixels=${pixelCount}`);
      baselineMeans.push(meanVal);
    }
  }

  // Check if we have any valid baseline years
  const validBaseline = baselineMeans.filter(v => v !== null);
  if (validBaseline.length === 0) {
    console.log("C1: No valid baseline data (2000-2013).");
    console.log("<answer>C1</answer>");
    return;
  }

  // Compute baseline average
  const baselineAvg = validBaseline.reduce((a, b) => a + b, 0) / validBaseline.length;

  // 4. Process target year (2018)
  const targetCol = filterAndMask(targetYear);
  const targetCount = targetCol.size().getInfo();
  if (targetCount === 0) {
    console.log("C1: No images for 2018.");
    console.log("<answer>C1</answer>");
    return;
  }
  const targetMeanImg = targetCol.mean();
  const targetStats = targetMeanImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });
  const targetMean = targetStats.get('NDVI').getInfo();
  const targetPixelCount = targetMeanImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();
  if (targetPixelCount === 0) {
    console.log("C2: No valid pixels for 2018 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Baseline (2000-2013 JJA) avg NDVI: ${baselineAvg.toFixed(4)} (from ${validBaseline.length} years)`);
  console.log(`2018 JJA mean NDVI: ${targetMean ? targetMean.toFixed(4) : 'null'}, Pixels: ${targetPixelCount}`);

  // Check for invalid calculations
  if (targetMean === null || targetMean === undefined || isNaN(targetMean) || 
      baselineAvg === null || isNaN(baselineAvg)) {
    console.log("C3: Calculation failure (null/NaN).");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare: decrease means targetMean < baselineAvg
  if (targetMean < baselineAvg) {
    console.log("A: Yes (NDVI decreased).");
    console.log("<answer>A</answer>");
  } else {
    console.log("B: No (NDVI did not decrease).");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
